-- Fuente cruda TNR. Ejecutar en una base nueva.
BEGIN;
CREATE TABLE ventas_crudas (
    fila_origen INTEGER PRIMARY KEY,
    id_venta TEXT,
    fecha TEXT,
    rut_cliente TEXT,
    nombre_cliente TEXT,
    id_producto TEXT,
    id_tienda TEXT,
    ciudad_tienda TEXT,
    cantidad INTEGER,
    precio_unitario TEXT,
    canal TEXT,
    observaciones TEXT,
    id_pedido_omnicanal TEXT,
    modalidad_entrega TEXT,
    id_ubicacion_despacho TEXT,
    estado_venta TEXT,
    costo_unitario_aplicado_clp INTEGER
);
CREATE INDEX idx_ventas_crudas_id_venta ON ventas_crudas (id_venta);
COMMIT;
